Arguments: {"title":"Parse top 50 schools from CSRankings","cwd":null,"code":"const csTab = 103795432;\nconst schools = await browserjs(csTab, () => {\n  const trs = Array.from(document.querySelectorAll(\"#ranking tbody tr\"));\n  const results = [];\n  trs.forEach(tr => {\n    const rankTd = tr.querySelector(\"td.rank-cell\");\n    if (!rankTd) return;\n    const rank = rankTd.innerText.trim();\n    // find school name and dept link\n    const nameSpan = tr.querySelector(\"td:nth-child(2) span[onclick*='toggleFaculty']:not([id*='widget'])\");\n    const linkA = tr.querySelector(\"td:nth-child(2) a[href]\");\n    results.push({\n      rank: rank,\n      name: nameSpan ? nameSpan.innerText.trim() : \"\",\n      deptUrl: linkA ? linkA.href : \"\"\n    });\n  });\n  return results;\n});\n\nconsole.log(\"Total schools parsed:\", schools.length);\nconsole.log(\"First 55 schools:\", JSON.stringify(schools.slice(0, 55), null, 2));\n\n// Save the top 50 list to a tmp file\nawait write(\"tmp://top50_cs_schools.json\", JSON.stringify(schools.slice(0, 55), null, 2));\n"}
