async function searchDDG(query) {
  const enc = encodeURIComponent(query);
  await tool.navigate({ tabId: searchTab, url: `https://html.duckduckgo.com/html/?q=${enc}` });
  await tool.wait_for({ tabId: searchTab, condition: "dom_settled", timeout_ms: 4000 });
  return await browserjs(searchTab, () => {
    return Array.from(document.querySelectorAll(".result__title a.result__url, .result__a")).map(a => {
      let realUrl = a.href;
      try {
        const u = new URL(a.href);
        if (u.searchParams.has("uddg")) realUrl = decodeURIComponent(u.searchParams.get("uddg"));
      } catch (e) {}
      return { title: a.innerText?.trim(), url: realUrl };
    }).filter(x => x.title && x.url && !x.url.includes("duckduckgo.com"));
  });
}

